//! Retained output admission, using the vendored `KaTeX` 0.18.4 `MathML` vocabulary.

use gazette_adapter_markdown::math::validate;
use gazette_core::markdown::Error;

#[test]
fn captured_real_corpus_operator_scripts_pass_strict_admission_and_both_formatters() {
    use gazette_adapter_markdown::Comrak;
    use gazette_core::{
        markdown::{Limits, MathBinding, Plan, Profile},
        source::Sha256Digest,
    };
    use gazette_ports::markdown::Markdown;

    // Generated by the actual retained Node/KaTeX owner. Its native test proves
    // every complete byte string still equals current provider output.
    let captured: serde_json::Value = serde_json::from_str(include_str!(
        "../../math/tests/fixtures/script-operands.json"
    ))
    .expect("captured native provider fixture");
    let formulas = captured["formulas"].as_array().unwrap();
    let outputs = captured["mathml"].as_array().unwrap();
    assert_eq!(formulas.len(), 12);
    assert_eq!(formulas.len(), outputs.len());
    for (formula, output) in formulas.iter().zip(outputs) {
        let tex = formula["tex"].as_str().unwrap();
        let display = formula["display"].as_bool().unwrap();
        let mathml = output.as_str().unwrap();
        assert_eq!(validate(mathml, tex, display), Ok(()), "{tex}");
        let delimiter = if display { "$$" } else { "$" };
        let source = format!("α before {delimiter}{tex}{delimiter} after.\r\n");
        let document = Comrak
            .parse(&source, Profile::PublicationMath, Limits::default())
            .expect("actual native source analysis");
        let syntax = document.syntax();
        assert_eq!(syntax.math.len(), 1, "{tex}");
        let occurrence = syntax.math[0].clone();
        assert_eq!(occurrence.tex, tex);
        assert_eq!(occurrence.display, display);
        assert!(occurrence.emitted);
        assert_eq!(
            occurrence.location.span.slice(&source).unwrap(),
            format!("{delimiter}{tex}{delimiter}")
        );
        let selected = Plan {
            identity: syntax.identity,
            headings: vec![],
            links: vec![],
            footnotes: vec![],
            excerpt: None,
            math: vec![MathBinding {
                occurrence,
                mathml: mathml.to_owned(),
            }],
            components: vec![],
        };
        let rendered = document
            .render(&selected, None)
            .expect("strict complete source-bound HTML plan");
        let markdown = document
            .render_markdown(&selected, None)
            .expect("same source-bound Markdown plan");
        assert!(rendered.body.html.contains(mathml), "{tex}");
        assert!(markdown.contains(tex), "{tex}: {markdown}");
        assert!(!markdown.contains("<math"), "{tex}: {markdown}");
        assert!(rendered.body.text.contains(tex));
        assert_eq!(
            syntax.identity.source_sha256,
            Sha256Digest::of(source.as_bytes())
        );
        assert_eq!(
            document.render(&selected, None).unwrap(),
            rendered,
            "retained replay must not normalize or re-typeset the formula"
        );
        // The former malformed provider spelling remains refused. The fix is
        // solely at generation, not a weakening of script arity or TeX binding.
        let mut malformed = selected;
        malformed.math[0].mathml = mathml
            .replace(
                "<mrow><mi>log</mi><mo>⁡</mo></mrow>",
                "<mi>log</mi><mo>⁡</mo>",
            )
            .replace(
                "<mrow><mi>min</mi><mo>⁡</mo></mrow>",
                "<mi>min</mi><mo>⁡</mo>",
            )
            .replace(
                "<mrow><mi>max</mi><mo>⁡</mo></mrow>",
                "<mi>max</mi><mo>⁡</mo>",
            )
            .replace(
                "<mrow><mi mathvariant=\"normal\">clamp</mi><mo>⁡</mo></mrow>",
                "<mi mathvariant=\"normal\">clamp</mi><mo>⁡</mo>",
            );
        assert_ne!(malformed.math[0].mathml, mathml, "{tex}");
        assert_eq!(document.render(&malformed, None), Err(Error::InvalidPlan));
        assert_eq!(
            document.render_markdown(&malformed, None),
            Err(Error::InvalidPlan)
        );
    }
}

fn fragment(body: &str, tex: &str, display: bool) -> String {
    let escaped = tex
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;");
    let mode = if display { " display=\"block\"" } else { "" };
    format!(
        "<math xmlns=\"http://www.w3.org/1998/Math/MathML\"{mode}><semantics>{body}<annotation encoding=\"application/x-tex\">{escaped}</annotation></semantics></math>"
    )
}

#[test]
fn real_katex_inline_display_structures_and_exact_annotations_are_admitted() {
    // Bodies captured from the retained 0.18.4 module, not hand-authored TeX parsing.
    let samples = [
        ("x+1", "<mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow>"),
        (
            r"\frac{a}{b}",
            "<mrow><mfrac><mi>a</mi><mi>b</mi></mfrac></mrow>",
        ),
        (
            r"\sqrt{x^2+y_1}",
            "<mrow><msqrt><mrow><msup><mi>x</mi><mn>2</mn></msup><mo>+</mo><msub><mi>y</mi><mn>1</mn></msub></mrow></msqrt></mrow>",
        ),
        (
            r"\color{red}{x}",
            "<mrow><mstyle mathcolor=\"red\"><mi>x</mi></mstyle></mrow>",
        ),
        (
            r"\boldsymbol{x}",
            "<mrow><mi mathvariant=\"bold-italic\">x</mi></mrow>",
        ),
        (
            r"\sum_{i=0}^n i",
            "<mrow><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>0</mn></mrow><mi>n</mi></munderover><mi>i</mi></mrow>",
        ),
        (
            r"\fcolorbox{red}{yellow}{x}",
            "<mrow><mpadded width=\"+6pt\" height=\"+6pt\" lspace=\"3pt\" voffset=\"3pt\" style=\"border: 0.04em solid red\" mathbackground=\"yellow\"><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mtext>x</mtext></mstyle></mpadded></mrow>",
        ),
    ];
    for (tex, body) in samples {
        for display in [false, true] {
            assert_eq!(
                validate(&fragment(body, tex, display), tex, display),
                Ok(()),
                "{tex}"
            );
        }
    }
    let tex = "x < y\n\\& z";
    let retained = fragment("<mrow><mi>x</mi><mo>&lt;</mo><mi>y</mi></mrow>", tex, false);
    assert_eq!(validate(&retained, tex, false), Ok(()));
    assert_eq!(
        validate(&retained, "different", false),
        Err(Error::InvalidPlan)
    );
    assert_eq!(validate(&retained, tex, true), Err(Error::InvalidPlan));
}

#[test]
fn real_katex_tables_keep_alignment_spacing_and_projected_tags() {
    let tex = r"\begin{pmatrix}a&b\\c&d\end{pmatrix}";
    let body = "<mrow><mo fence=\"true\">(</mo><mtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mi>a</mi></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mi>b</mi></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mi>c</mi></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mi>d</mi></mstyle></mtd></mtr></mtable><mo fence=\"true\">)</mo></mrow>";
    assert_eq!(validate(&fragment(body, tex, true), tex, true), Ok(()));
    let tagged = "<mtable width=\"100%\"><mtr><mtd width=\"50%\"></mtd><mtd><mi>x</mi></mtd><mtd width=\"50%\"></mtd><mtd><mtext>(1)</mtext></mtd></mtr></mtable>";
    assert_eq!(
        validate(&fragment(tagged, r"\tag{1}x", true), r"\tag{1}x", true),
        Ok(())
    );
}

#[test]
fn malformed_active_unknown_and_external_markup_is_refused() {
    for body in [
        "<script>alert(1)</script>",
        "<svg><script/></svg>",
        "<mglyph src=\"https://example.test/x\"/>",
        "<mi href=\"https://example.test/\">x</mi>",
        "<mi src=\"file:///private\">x</mi>",
        "<mi id=\"owned\">x</mi>",
        "<mi onclick=\"run()\">x</mi>",
        "<mi data-value=\"x\">x</mi>",
        "<maction><mi>x</mi></maction>",
        "<annotation-xml encoding=\"text/html\"><img/></annotation-xml>",
        "<mi><math><mi>x</mi></math></mi>",
        "<mrow><mi>x</mrow>",
        "<mfrac><mi>x</mi></mfrac>",
        "<mtable><mi>x</mi></mtable>",
        "<mi mathcolor=red>x</mi>",
        "<mi>&unknown;</mi>",
        "<mi><![CDATA[x]]></mi>",
        "<mi><!-- x -->x</mi>",
        "<mi><?target x?>x</mi>",
    ] {
        assert_eq!(
            validate(&fragment(body, "x", false), "x", false),
            Err(Error::InvalidPlan),
            "{body}"
        );
    }
    let valid = fragment("<mi>x</mi>", "x", false);
    for altered in [
        format!("<!DOCTYPE math [<!ENTITY x SYSTEM 'file:///private'>]>{valid}"),
        format!("<?xml version=\"1.0\"?>{valid}"),
        format!("{valid}{valid}"),
        format!("<span class=\"katex\">{valid}</span>"),
        valid.replace("<mi>x</mi>", "<!DOCTYPE math><mi>x</mi>"),
    ] {
        assert_eq!(validate(&altered, "x", false), Err(Error::InvalidPlan));
    }
}

#[test]
fn native_duplicate_and_namespace_checks_do_not_hide_lexical_ambiguity() {
    for body in [
        "<mo stretchy=\"true\" stretchy=\"false\">x</mo>",
        "<mi xmlns=\"http://www.w3.org/1998/Math/MathML\">x</mi>",
        "<mi xmlns=\"http://www.w3.org/1998/Math/MathML\" xmlns=\"http://www.w3.org/1998/Math/MathML\">x</mi>",
        "<mi xmlns=\"http://www.w3.org/1999/xhtml\">x</mi>",
        "<mi xmlns:unused=\"https://example.test/ns\">x</mi>",
        "<mi xml:lang=\"en\">x</mi>",
        "<m:mi xmlns:m=\"http://www.w3.org/1998/Math/MathML\">x</m:mi>",
    ] {
        assert_eq!(
            validate(&fragment(body, "x", false), "x", false),
            Err(Error::InvalidPlan),
            "{body}"
        );
    }
    let valid = fragment("<mi>x</mi>", "x", false);
    for root in [
        "<math>",
        "<math xmlns=\"http://www.w3.org/1999/xhtml\">",
        "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" xmlns=\"http://www.w3.org/1998/Math/MathML\">",
        "<math xmlns=\"http://www.w3.org/1998/Math/MathML\" xmlns:x=\"urn:x\">",
    ] {
        let altered = valid.replacen(
            "<math xmlns=\"http://www.w3.org/1998/Math/MathML\">",
            root,
            1,
        );
        assert_eq!(validate(&altered, "x", false), Err(Error::InvalidPlan));
    }
}

#[test]
fn annotation_requires_one_terminal_exact_tex_binding() {
    let valid = fragment("<mi>x</mi>", "x", false);
    let annotation = "<annotation encoding=\"application/x-tex\">x</annotation>";
    for altered in [
        valid.replace(annotation, ""),
        valid.replace(annotation, &format!("{annotation}{annotation}")),
        valid.replace(
            annotation,
            "<annotation encoding=\"text/html\">x</annotation>",
        ),
        valid.replace(annotation, "<annotation>x</annotation>"),
        valid.replace(
            annotation,
            "<annotation encoding=\"application/x-tex\"><mi>x</mi></annotation>",
        ),
        valid.replace(
            annotation,
            "<annotation encoding=\"application/x-tex\">x </annotation>",
        ),
        valid.replace("<mi>x</mi>", annotation),
    ] {
        assert_eq!(validate(&altered, "x", false), Err(Error::InvalidPlan));
    }
}

#[test]
fn css_and_dimensions_are_native_bounded_tokens_not_arbitrary_style() {
    for body in [
        "<mstyle style=\"text-shadow: 0.02em 0.01em 0.04px\"><mi>x</mi></mstyle>",
        "<mpadded style=\"border: 0.04em solid #f00\"><mi>x</mi></mpadded>",
        "<mpadded lspace=\"-1width\" width=\"0px\"><mi>x</mi></mpadded>",
        "<mspace width=\"0.25em\"/>",
    ] {
        assert_eq!(
            validate(&fragment(body, "x", false), "x", false),
            Ok(()),
            "{body}"
        );
    }
    for body in [
        "<mstyle style=\"background:url(https://example.test/x)\"><mi>x</mi></mstyle>",
        "<mstyle style=\"text-shadow: 0em 0em 0em;position:fixed\"><mi>x</mi></mstyle>",
        "<mpadded style=\"border: 1em solid var(--secret)\"><mi>x</mi></mpadded>",
        "<mspace width=\"calc(1em + 2em)\"/>",
        "<mspace width=\"NaN\"/>",
        "<mspace width=\"1e30em\"/>",
        "<mspace width=\"0.25em 1em\"/>",
        "<mstyle mathcolor=\"url(https://example.test/x)\"><mi>x</mi></mstyle>",
        "<mi class=\"arbitrary\">x</mi>",
        "<mo stretchy=\"TRUE\">x</mo>",
    ] {
        assert_eq!(
            validate(&fragment(body, "x", false), "x", false),
            Err(Error::InvalidPlan),
            "{body}"
        );
    }
}

#[test]
fn input_depth_events_and_attribute_bounds_fail_without_admission() {
    assert!(matches!(
        validate(&"x".repeat((128 << 10) + 1), "x", false),
        Err(Error::Limit(_))
    ));
    assert!(matches!(
        validate(
            &fragment("<mi>x</mi>", &"x".repeat((8 << 10) + 1), false),
            &"x".repeat((8 << 10) + 1),
            false
        ),
        Err(Error::Limit(_))
    ));
    let deep = format!("{}<mi>x</mi>{}", "<mrow>".repeat(65), "</mrow>".repeat(65));
    assert!(matches!(
        validate(&fragment(&deep, "x", false), "x", false),
        Err(Error::Limit(_))
    ));
    let many = format!("<mrow>{}</mrow>", "<mi>x</mi>".repeat(8_000));
    assert!(matches!(
        validate(&fragment(&many, "x", false), "x", false),
        Err(Error::Limit(_))
    ));
    let large_attribute = format!(
        "<mstyle mathcolor=\"{}\"><mi>x</mi></mstyle>",
        "x".repeat((8 << 10) + 1)
    );
    assert!(matches!(
        validate(&fragment(&large_attribute, "x", false), "x", false),
        Err(Error::Limit(_))
    ));
}
